def zipStrs(first: str, second: str) -> str:
    result = []
    i = 0
    while i < len(first) or i < len(second):
        if i < len(first):
            result.append(first[i])
        if i < len(second):
            result.append(second[i])
        i += 1
    return ''.join(result)

def main() -> None:
    test_cases = [
        ("", ""),
        ("", "abc"),
        ("abc", ""),
        ("a", "123"),
        ("ab", "123"),
        ("abc", "1"),
        ("abc", "123"),
        ("Hello", "World!"),
        ("ace", "bdf"),
        ("1234567890", "xyz"),
    ]
    for first, second in test_cases:
        result = zipStrs(first, second)
        print(result)

if __name__ == "__main__":
    main()

