#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* zipStrs(const char* first, const char* second) {
    if (first == NULL || second == NULL) {
        char* empty = malloc(1);
        if (empty) empty[0] = '\0';
        return empty;
    }

    size_t len1 = strlen(first);
    size_t len2 = strlen(second);
    size_t max_len = len1 > len2 ? len1 : len2;

    char* result = malloc(len1 + len2 + 1);
    if (result == NULL) return NULL;

    size_t idx = 0;
    for (size_t i = 0; i < max_len; i++) {
        if (i < len1) {
            result[idx++] = first[i];
        }
        if (i < len2) {
            result[idx++] = second[i];
        }
    }
    result[idx] = '\0';

    return result;
}

void test_zipStrs(const char* first, const char* second, const char* expected) {
    char* result = zipStrs(first, second);
    printf("zipStrs(\"%s\", \"%s\") = \"%s\"", first, second, result);
    if (strcmp(result, expected) == 0) {
        printf(" ✓\n");
    } else {
        printf(" ✗ (expected \"%s\")\n", expected);
    }
    free(result);
}

int main() {
    printf("Testing zipStrs function:\n");
    printf("=========================\n");

    test_zipStrs("abc", "123", "a1b2c3");
    test_zipStrs("Hello", "World", "HWeolrllod");
    test_zipStrs("short", "verylongstring", "svhoerrtlongstring");
    test_zipStrs("", "nonempty", "nonempty");
    test_zipStrs("nonempty", "", "nonempty");
    test_zipStrs("", "", "");
    test_zipStrs("A", "1", "A1");
    test_zipStrs("AB", "1", "A1B");

    return 0;
}

