import java.util.*;

public class Solution {
    public static String zipStrs(String first, String second) {
        if (first == null || second == null) {
            return "";
        }
        int n = first.length();
        int m = second.length();
        int i = 0;
        int j = 0;
        StringBuilder result = new StringBuilder();
        while (i < n && j < m) {
            result.append(first.charAt(i));
            result.append(second.charAt(j));
            i++;
            j++;
        }
        while (i < n) {
            result.append(first.charAt(i));
            i++;
        }
        while (j < m) {
            result.append(second.charAt(j));
            j++;
        }
        return result.toString();
    }

    public static void main(String[] args) {
        System.out.println(zipStrs("abc", "123"));
        System.out.println(zipStrs("abcd", "12"));
        System.out.println(zipStrs("ab", "1234"));
        System.out.println(zipStrs("", "xyz"));
        System.out.println(zipStrs("hello", ""));
        System.out.println(zipStrs("", ""));
        System.out.println(zipStrs("A", "1"));
        System.out.println(zipStrs("AB", "12"));
        System.out.println(zipStrs("ABC", "1"));
        System.out.println(zipStrs("X", "YZ"));
    }
}
